//! External GDK binding: source files stay read only; only the unique owned EXE is created.
use std::{fs::{self,File,OpenOptions},io::{Read,Write},path::{Path,PathBuf}};
use serde::{Deserialize,Serialize};
use sha2::{Digest,Sha256};
use crate::error::KernelError;
use super::meta::VersionMeta;
const BINDING:&str="copper-external-binding.json";
const MAX_EXE:u64=1024*1024*1024;
#[derive(Clone,Debug,Serialize,Deserialize,PartialEq,Eq)]
pub struct DisplayStamp{path:PathBuf,size:u64,modified:u128,identity:String}
fn display_stamp(path:&Path)->Result<DisplayStamp,KernelError>{regular_path(path)?;let file=File::open(path)?;let m=file.metadata()?;let modified=m.modified()?.duration_since(std::time::UNIX_EPOCH).map_err(|_|fail("compat_source_changed"))?.as_nanos();
 #[cfg(windows)]let identity={use std::os::windows::io::AsRawHandle;use windows::Win32::{Foundation::HANDLE,Storage::FileSystem::{GetFileInformationByHandle,BY_HANDLE_FILE_INFORMATION}};let mut info=BY_HANDLE_FILE_INFORMATION::default();unsafe{GetFileInformationByHandle(HANDLE(file.as_raw_handle()),&mut info)}.map_err(|_|fail("compat_source_missing"))?;format!("{}:{}:{}",info.dwVolumeSerialNumber,info.nFileIndexHigh,info.nFileIndexLow)};
 #[cfg(not(windows))]let identity=format!("{:?}",m.created().ok());
 Ok(DisplayStamp{path:fs::canonicalize(path)?,size:m.len(),modified,identity})}
fn display_stamps(b:&Binding)->Result<Vec<DisplayStamp>,KernelError>{["Minecraft.Windows.exe","Minecraft.Windows.exe.orig","MicrosoftGame.config","version.json",b.derived_name.as_str()].iter().map(|n|display_stamp(&b.source_dir.join(n))).collect()}

fn fail(s:&str)->KernelError{KernelError::InvalidArgument(s.into())}
#[derive(Clone,Debug,Serialize,Deserialize,PartialEq,Eq)]
pub struct Fingerprint{pub hash:String,pub size:u64}
#[derive(Clone,Debug,Serialize,Deserialize)]
pub struct Binding{pub schema:u32,pub id:String,pub source_dir:PathBuf,pub derived_name:String,pub derived_hash:String,pub source_exe:Fingerprint,pub original:Fingerprint,pub config:Fingerprint,pub metadata:Fingerprint,pub version:[u16;4],#[serde(default)]pub display_stamps:Vec<DisplayStamp>}
#[derive(Clone,Debug,Serialize)]
pub struct Capabilities{pub launch:bool,pub detach:bool,pub rename:bool,pub shared_save:bool,pub loader:bool,pub client:bool,pub source_write:bool}
#[derive(Clone,Debug,Serialize)]
pub struct CompatibilityStatus{pub state:String,pub disabled_reason:Option<String>,pub source_dir:String,pub capabilities:Capabilities,pub data_mode:&'static str}
#[derive(Clone,Debug,Serialize)]
pub struct CompatibilityProbe{pub supported:bool,pub disabled_reason:Option<String>,pub source_dir:String,pub game_version:Option<String>,pub version_type:Option<String>}
fn regular_path(path:&Path)->Result<(),KernelError>{for p in path.ancestors(){let m=fs::symlink_metadata(p)?;if m.file_type().is_symlink(){return Err(fail("compat_reparse_unsupported"));}#[cfg(windows)]{use std::os::windows::fs::MetadataExt;if m.file_attributes()&0x400!=0{return Err(fail("compat_reparse_unsupported"));}}}Ok(())}
fn read_locked(path:&Path,limit:u64)->Result<(File,Vec<u8>,Fingerprint),KernelError>{
 regular_path(path)?;let mut options=OpenOptions::new();options.read(true);#[cfg(windows)]{use std::os::windows::fs::OpenOptionsExt;options.share_mode(1);}
 let mut f=options.open(path)?;let m=f.metadata()?;if !m.is_file()||m.len()>limit{return Err(fail("compat_source_invalid"));}let mut bytes=Vec::new();(&mut f).take(limit+1).read_to_end(&mut bytes)?;if bytes.len()as u64!=m.len(){return Err(fail("compat_source_changed"));}let fp=Fingerprint{hash:format!("{:x}",Sha256::digest(&bytes)),size:m.len()};Ok((f,bytes,fp))
}
// Structural version binding is deliberately separate from proof of official authenticity.
fn version(b:&[u8])->Result<[u16;4],KernelError>{let mut out=Vec::new();for(i,w)in b.windows(8).enumerate(){if w==[0xbd,4,0xef,0xfe,0,0,1,0]{if let Some(v)=b.get(i+8..i+16){let h=u32::from_le_bytes(v[..4].try_into().unwrap());let l=u32::from_le_bytes(v[4..].try_into().unwrap());out.push([(h>>16)as u16,h as u16,(l>>16)as u16,l as u16]);}}}out.sort();out.dedup();if out.len()!=1{return Err(fail("compat_version_unverifiable"));}Ok(out[0])}
fn validate_image(b:&[u8],clean:bool)->Result<[u16;4],KernelError>{let image=crate::pe::parse(b.to_vec()).map_err(|_|fail("compat_invalid_pe"))?;if image.machine!=0x8664{return Err(fail("compat_architecture_unsupported"));}if clean{for dll in["LeviLauncher.dll","CopperCoreHook.dll","PreLoader.dll","LeviLamina.dll"]{if image.dll_is_imported(dll).map_err(|_|fail("compat_invalid_pe"))?{return Err(fail("compat_original_patched"));}}}let section=image.sections.iter().find(|s|s.name==".rsrc").ok_or_else(||fail("compat_version_unverifiable"))?;let start=section.pointer_to_raw_data as usize;let end=start.checked_add(section.size_of_raw_data as usize).ok_or_else(||fail("compat_invalid_pe"))?;version(b.get(start..end).ok_or_else(||fail("compat_invalid_pe"))?)}
struct Source{binding:Binding,meta:VersionMeta,bytes:Vec<u8>,leases:Vec<File>}
fn inspect(source:&Path)->Result<Source,KernelError>{
 if !cfg!(windows){return Err(fail("compat_platform_unsupported"));}regular_path(source)?;let root=fs::canonicalize(source)?;
 let(mf,mb,metadata)=read_locked(&root.join("version.json"),4*1024*1024)?;let meta:VersionMeta=serde_json::from_slice(&mb).map_err(|_|fail("compat_metadata_invalid"))?;
 if meta.is_uwp()||meta.android.is_some()||meta.package_type.as_deref().is_some_and(|p|p!="gdk"){return Err(fail("compat_gdk_required"));}
 let(cf,cb,config)=read_locked(&root.join("MicrosoftGame.config"),4*1024*1024).map_err(|_|fail("compat_gdk_required"))?;
 let(sf,sb,source_exe)=read_locked(&root.join("Minecraft.Windows.exe"),MAX_EXE)?;let op=root.join("Minecraft.Windows.exe.orig");if !op.is_file(){return Err(fail("compat_orig_missing"));}let(of,bytes,original)=read_locked(&op,MAX_EXE)?;
 let v=validate_image(&bytes,true)?;if validate_image(&sb,false)?!=v{return Err(fail("compat_version_mismatch"));}let expected=meta.game_version.split('.').map(str::parse::<u16>).collect::<Result<Vec<_>,_>>().map_err(|_|fail("compat_version_mismatch"))?;if expected.as_slice()!=v{return Err(fail("compat_version_mismatch"));}
 let mut reader=quick_xml::Reader::from_reader(cb.as_slice());let mut matched=false;loop{match reader.read_event(){Ok(quick_xml::events::Event::Start(e)|quick_xml::events::Event::Empty(e))if e.local_name().as_ref()==b"Identity"=>{for a in e.attributes(){let a=a.map_err(|_|fail("compat_gdk_required"))?;if a.key.as_ref()==b"Version"{let t=a.decode_and_unescape_value(reader.decoder()).map_err(|_|fail("compat_gdk_required"))?;let p=t.split('.').map(str::parse::<u16>).collect::<Result<Vec<_>,_>>().map_err(|_|fail("compat_version_mismatch"))?;matched=p.as_slice()==v;}}},Ok(quick_xml::events::Event::Eof)=>break,Err(_)=>return Err(fail("compat_gdk_required")),_=>{}}}if !matched{return Err(fail("compat_version_mismatch"));}
 if super::launch::is_process_running_at_path(&root.join("Minecraft.Windows.exe")){return Err(fail("compat_game_running"));}
 if let Ok(entries)=fs::read_dir(&root){for e in entries.flatten(){let n=e.file_name();let n=n.to_string_lossy();if n.starts_with("Minecraft.Copper.")&&n.ends_with(".exe")&&super::launch::is_process_running_at_path(&e.path()){return Err(fail("compat_game_running"));}}}
 Ok(Source{binding:Binding{schema:1,id:uuid::Uuid::new_v4().to_string(),source_dir:root,derived_name:String::new(),derived_hash:original.hash.clone(),source_exe,original,config,metadata,version:v,display_stamps:Vec::new()},meta,bytes,leases:vec![mf,cf,sf,of]})
}
fn reason(e:&KernelError)->String{match e{KernelError::InvalidArgument(s)if s.starts_with("compat_")=>s.clone(),_=>"compat_source_missing".into()}}
pub fn discover()->Vec<String>{
 if !cfg!(windows){return Vec::new();}let Some(app)=std::env::var_os("APPDATA")else{return Vec::new();};let base=PathBuf::from(app);let mut out=Vec::new();
 if let Ok(entries)=fs::read_dir(&base){for entry in entries.flatten().take(512){let name=entry.file_name().to_string_lossy().to_ascii_lowercase();if !name.contains("levi")||!name.ends_with(".exe"){continue;}let config=entry.path().join("config.json");let mut root=entry.path();if let Ok((_,bytes,_))=read_locked(&config,1024*1024){if let Ok(value)=serde_json::from_slice::<serde_json::Value>(&bytes){if let Some(p)=value.get("base_root").and_then(|v|v.as_str()).filter(|v|!v.trim().is_empty()){root=PathBuf::from(p);}}}if let Ok(items)=fs::read_dir(root.join("versions")){for item in items.flatten().take(2048){let p=item.path();if regular_path(&p).is_ok()&&p.join("version.json").is_file(){out.push(p.to_string_lossy().into_owned());}}}}}out.sort();out.dedup();out
}
pub fn probe(source:&Path)->CompatibilityProbe{match inspect(source){Ok(s)=>CompatibilityProbe{supported:true,disabled_reason:None,source_dir:s.binding.source_dir.to_string_lossy().into_owned(),game_version:Some(s.meta.game_version),version_type:Some(s.meta.version_type)},Err(e)=>CompatibilityProbe{supported:false,disabled_reason:Some(reason(&e)),source_dir:source.to_string_lossy().into_owned(),game_version:None,version_type:None}}}
pub fn read(control:&Path)->Result<Option<Binding>,KernelError>{let p=control.join(BINDING);if !p.exists(){return Ok(None);}let(_,bytes,_)=read_locked(&p,1024*1024)?;let b:Binding=serde_json::from_slice(&bytes).map_err(|_|fail("compat_binding_invalid"))?;if b.schema!=1||uuid::Uuid::parse_str(&b.id).is_err()||b.derived_name!=format!("Minecraft.Copper.{}.exe",b.id){return Err(fail("compat_binding_invalid"));}Ok(Some(b))}
pub fn is_bound(control:&Path)->bool{control.join(BINDING).exists()}
pub fn bind(root:&Path,source:&Path,alias:&str)->Result<(),KernelError>{
 super::meta::validate_version_name(root,alias)?;let mut s=inspect(source)?;let control=root.join(alias);fs::create_dir(&control)?;s.binding.derived_name=format!("Minecraft.Copper.{}.exe",s.binding.id);let target=s.binding.source_dir.join(&s.binding.derived_name);
 let mut created=false;let result=(||{let mut f=OpenOptions::new().write(true).create_new(true).open(&target)?;created=true;f.write_all(&s.bytes)?;f.sync_all()?;
 s.meta.name=alias.into();s.meta.mode=Some("original".into());s.meta.loader=None;s.meta.client_id=None;s.meta.client_dll=None;s.meta.launch_args.clear();s.meta.env_vars.clear();s.meta.enable_isolation=true;s.meta.enable_editor_mode=false;s.meta.enable_console=false;s.meta.registered=false;VersionMeta::write(&control,&s.meta)?;
 s.binding.display_stamps=display_stamps(&s.binding)?;
 let mut m=OpenOptions::new().write(true).create_new(true).open(control.join(BINDING))?;m.write_all(&serde_json::to_vec_pretty(&s.binding).map_err(|_|fail("compat_binding_invalid"))?)?;m.sync_all()?;Ok::<_,KernelError>(())})();
 if result.is_err(){if created{if let Ok((lease,_,fp))=read_locked(&target,MAX_EXE){drop(lease);if fp.hash==s.binding.derived_hash{let _=fs::remove_file(&target);}}}let _=fs::remove_dir_all(&control);}result
}
pub struct ResolvedLaunchSpec{pub source_root:PathBuf,pub executable:PathBuf,pub leases:Vec<File>}
pub fn resolve(control:&Path)->Result<ResolvedLaunchSpec,KernelError>{let b=read(control)?.ok_or_else(||fail("compat_binding_invalid"))?;let s=inspect(&b.source_dir)?;if s.binding.source_exe!=b.source_exe||s.binding.original!=b.original||s.binding.config!=b.config||s.binding.metadata!=b.metadata||s.binding.version!=b.version{return Err(fail("compat_source_changed"));}let exe=b.source_dir.join(&b.derived_name);let(lease,_,fp)=read_locked(&exe,MAX_EXE)?;if fp.hash!=b.derived_hash{return Err(fail("compat_owned_exe_changed"));}let mut leases=s.leases;leases.push(lease);Ok(ResolvedLaunchSpec{source_root:b.source_dir,executable:exe,leases})}
pub fn status(control:&Path)->Option<CompatibilityStatus>{if !is_bound(control){return None;}let binding=read(control);let r=binding.as_ref().map_err(|_|fail("compat_binding_invalid")).and_then(|b|b.as_ref().ok_or_else(||fail("compat_binding_invalid"))).and_then(|b|{let stamps=display_stamps(b)?;if b.display_stamps.len()!=5||stamps!=b.display_stamps{return Err(fail("compat_source_changed"));}Ok(())});let why=r.as_ref().err().map(reason);let source=binding.ok().flatten().map(|b|b.source_dir.to_string_lossy().into_owned()).unwrap_or_default();Some(CompatibilityStatus{state:if why.is_none(){"bound"}else{"disabled"}.into(),disabled_reason:why,source_dir:source,capabilities:Capabilities{launch:r.is_ok(),detach:true,rename:true,shared_save:false,loader:false,client:false,source_write:false},data_mode:"private-save"})}
pub fn executable(control:&Path)->PathBuf{read(control).ok().flatten().map(|b|b.source_dir.join(b.derived_name)).unwrap_or_else(||control.join("Minecraft.Windows.exe"))}
pub fn detach(control:&Path)->Result<(),KernelError>{let b=read(control)?.ok_or_else(||fail("compat_binding_invalid"))?;let exe=b.source_dir.join(&b.derived_name);if super::launch::is_process_running_at_path(&exe){return Err(fail("compat_game_running"));}if let Ok((lease,_,fp))=read_locked(&exe,MAX_EXE){drop(lease);if fp.hash==b.derived_hash{fs::remove_file(exe)?;}}fs::remove_dir_all(control)?;Ok(())}
#[cfg(test)]mod tests{use super::*;
fn fixture()->Vec<u8>{let mut b=vec![0u8;1024];b[..2].copy_from_slice(&[77,90]);b[60..64].copy_from_slice(&128u32.to_le_bytes());b[128..132].copy_from_slice(&[80,69,0,0]);b[132..134].copy_from_slice(&0x8664u16.to_le_bytes());b[134..136].copy_from_slice(&1u16.to_le_bytes());b[148..150].copy_from_slice(&240u16.to_le_bytes());b[152..154].copy_from_slice(&0x20bu16.to_le_bytes());b[184..188].copy_from_slice(&4096u32.to_le_bytes());b[188..192].copy_from_slice(&512u32.to_le_bytes());b[208..212].copy_from_slice(&8192u32.to_le_bytes());b[212..216].copy_from_slice(&512u32.to_le_bytes());b[392..397].copy_from_slice(b".rsrc");b[400..404].copy_from_slice(&512u32.to_le_bytes());b[404..408].copy_from_slice(&4096u32.to_le_bytes());b[408..412].copy_from_slice(&512u32.to_le_bytes());b[412..416].copy_from_slice(&512u32.to_le_bytes());b[600..608].copy_from_slice(&[0xbd,4,0xef,0xfe,0,0,1,0]);b[608..612].copy_from_slice(&0x0001001au32.to_le_bytes());b[612..616].copy_from_slice(&0x00020003u32.to_le_bytes());b}
#[test]#[cfg(windows)]fn bind_drift_and_detach_preserve_source(){let temp=std::env::temp_dir().join(uuid::Uuid::new_v4().to_string());let source=temp.join("source");let root=temp.join("versions");fs::create_dir_all(&source).unwrap();fs::create_dir(&root).unwrap();let image=fixture();for n in ["Minecraft.Windows.exe","Minecraft.Windows.exe.orig"]{fs::write(source.join(n),&image).unwrap();}fs::write(source.join("MicrosoftGame.config"),b"<Game><Identity Version=\"1.26.2.3\"/></Game>").unwrap();let meta=VersionMeta{name:"source".into(),game_version:"1.26.2.3".into(),version_type:"release".into(),..Default::default()};VersionMeta::write(&source,&meta).unwrap();fs::write(source.join("PreLoader.dll"),b"foreign").unwrap();bind(&root,&source,"alias").unwrap();let control=root.join("alias");let binding=read(&control).unwrap().unwrap();assert_eq!(fs::read(source.join(&binding.derived_name)).unwrap(),image);assert!(resolve(&control).is_ok());assert_eq!(status(&control).unwrap().state,"bound");assert_eq!(fs::read(source.join("PreLoader.dll")).unwrap(),b"foreign");fs::write(source.join("MicrosoftGame.config"),b"changed").unwrap();assert!(resolve(&control).is_err());assert_eq!(status(&control).unwrap().state,"disabled");detach(&control).unwrap();assert!(!control.exists());assert!(source.join("Minecraft.Windows.exe").exists());assert!(source.join("Minecraft.Windows.exe.orig").exists());assert!(!source.join(binding.derived_name).exists());fs::remove_dir_all(temp).unwrap();}
#[test]#[cfg(windows)]fn owned_file_tamper_is_not_deleted(){let temp=std::env::temp_dir().join(uuid::Uuid::new_v4().to_string());let control=temp.join("control");let source=temp.join("source");fs::create_dir_all(&control).unwrap();fs::create_dir(&source).unwrap();let id=uuid::Uuid::new_v4().to_string();let name=format!("Minecraft.Copper.{id}.exe");fs::write(source.join(&name),b"changed").unwrap();let fp=Fingerprint{hash:"old".into(),size:0};let binding=Binding{schema:1,id,source_dir:source.clone(),derived_name:name.clone(),derived_hash:"old".into(),source_exe:fp.clone(),original:fp.clone(),config:fp.clone(),metadata:fp,version:[1,26,2,3],display_stamps:Vec::new()};fs::write(control.join(BINDING),serde_json::to_vec(&binding).unwrap()).unwrap();detach(&control).unwrap();assert_eq!(fs::read(source.join(name)).unwrap(),b"changed");fs::remove_dir_all(temp).unwrap();}
#[test]fn version_requires_unique_fixed_info(){assert!(version(b"none").is_err());let mut b=vec![0xbd,4,0xef,0xfe,0,0,1,0];b.extend_from_slice(&0x0001001au32.to_le_bytes());b.extend_from_slice(&0x00020003u32.to_le_bytes());assert_eq!(version(&b).unwrap(),[1,26,2,3]);let mut c=b.clone();c[8]=2;b.extend(c);assert!(version(&b).is_err());}
#[test]fn bad_alias_creates_nothing(){let r=std::env::temp_dir().join(uuid::Uuid::new_v4().to_string());fs::create_dir_all(&r).unwrap();assert!(bind(&r,Path::new("missing"),"../bad").is_err());assert!(fs::read_dir(&r).unwrap().next().is_none());fs::remove_dir(r).unwrap();}
}
